-- 모든 독립 패키지를 허용된 DB 규칙으로 정의한다. package_catalog는 검증 완료 전 비활성 상태를 유지한다.
START TRANSACTION;

ON DUPLICATE KEY UPDATE metadata_json=VALUES(metadata_json),enabled=0,row_version=row_version+1;

DELETE FROM package_reward_rules WHERE package_id IN ('PKG-078','PKG-088','PKG-093','PKG-097','PKG-098','PKG-100','PKG-103','PKG-105','PKG-156','PKG-157','PKG-158','PKG-159','PKG-160','PKG-161','PKG-162','PKG-165','PKG-166','PKG-186','PKG-188','PKG-201','PKG-203','PKG-204','PKG-206','PKG-207','PKG-208','PKG-209','PKG-210','PKG-211','PKG-212');


UPDATE package_catalog SET definition_status='RULES_SEEDED_DRAFT',enabled=0,row_version=row_version+1 WHERE package_id IN ('PKG-078','PKG-088','PKG-093','PKG-097','PKG-098','PKG-100','PKG-103','PKG-105','PKG-156','PKG-157','PKG-158','PKG-159','PKG-160','PKG-161','PKG-162','PKG-165','PKG-166','PKG-186','PKG-188','PKG-201','PKG-203','PKG-204','PKG-206','PKG-207','PKG-208','PKG-209','PKG-210','PKG-211','PKG-212');
